query:
SELECT id, name, chemicalFamily FROM molecules WHERE chemicalFamily = 'Norisoprénoïde' OR name LIKE '%Damasc%' OR name LIKE '%Solanone%' OR name LIKE '%Ionone%' LIMIT 15;
SELECT COUNT(*) as total_molecules FROM molecules;
SELECT COUNT(*) as total_plant_molecules FROM plant_molecules;

